using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text.Json;using g3;
class Runner{
 static object Snapshot(DMesh3 mesh,string label){mesh.CompactInPlace();if(!mesh.CheckValidity())throw new Exception("Invalid native mesh");var vertices=mesh.Vertices().Select(v=>new[]{v.x,v.y,v.z}).ToArray();var faces=mesh.Triangles().Select(t=>new[]{t.a,t.b,t.c}).ToArray();return new{label,closed=mesh.IsClosed(),mesh=new{vertices,faces}};}
 static void Main(string[] args){var generator=new Sphere3Generator_NormalizedCube(){EdgeVertices=8,Radius=1,NoSharedVertices=false};generator.Generate();var mesh=generator.MakeDMesh();var frames=new List<object>();if(!mesh.IsClosed())throw new Exception("Initial sphere is open");frames.Add(Snapshot(mesh,"Original sphere"));foreach(int tid in mesh.TriangleIndices().ToArray())if(mesh.GetTriCentroid(tid).y>.45)mesh.RemoveTriangle(tid);if(mesh.IsClosed())throw new Exception("Cut did not open mesh");frames.Add(Snapshot(mesh,"Open cap"));var loops=new MeshBoundaryLoops(mesh);if(loops.Count!=1)throw new Exception("Expected one hole, got "+loops.Count);foreach(var loop in loops.Loops){var fill=new SimpleHoleFiller(mesh,loop);if(!fill.Fill())throw new Exception("Native hole fill failed");}if(!mesh.IsClosed())throw new Exception("Repair remained open");frames.Add(Snapshot(mesh,"Native hole repair"));Directory.CreateDirectory(args[0]);File.WriteAllText(Path.Combine(args[0],"result.json"),JsonSerializer.Serialize(new{frames}));Console.WriteLine("PASS closed -> open -> repaired; native topology validation");}
}
